#!/usr/bin/env bash
# Every file added against origin/master declares its AI authorship (AGENTS.md §4).
#
# Generated by omp (DeepSeek V4.1 Flash) without human creative authorship.
# SPDX-License-Identifier: LGPL-2.1-or-later
#
# `--staged` reads the index instead of history, for the pre-commit hook: a
# HEAD-scoped scan cannot see the commit still being assembled, so the file
# that breaks the rule lands first and is caught one commit late.
#
# Exit codes: 0 every added file declares itself, 1 a file does not, 2 bad
# usage, 125 not applicable (no git checkout, or head mode without
# origin/master).

set -u

mode=${1:-head}
case "$mode" in
    head)   list='git diff --name-only --diff-filter=A origin/master...HEAD' ;;
    staged) list='git diff --cached --name-only --diff-filter=A' ;;
    *)      printf 'unknown mode: %s (want head|staged)\n' "$1" >&2; exit 2 ;;
esac
ROOT=$(git rev-parse --show-toplevel 2>/dev/null) || {
    printf 'SKIP  AI declarations (not inside a git checkout)\n'
    exit 125
}
cd "$ROOT" || exit 1

if [ "$mode" = head ] && ! git rev-parse --verify --quiet origin/master >/dev/null; then
    printf 'SKIP  AI declarations (origin/master is absent; fetch it first)\n'
    exit 125
fi

# The four declaration forms §4 accepts, plus the pre-#996 one-liner still
# carried by files written before the split.
declaration='(Architecture and design by|Fully generated by|Generated with assistance from|Generated by .*without human creative authorship|Reviewed and integrated by)'
authored='\.(py|sh|bash|rs|cpp|cc|cxx|c|h|hpp|go|js|mjs|ps1)$'

mapfile -t added < <(eval "$list" | grep -E "$authored" || true)

missing=0
checked=0
for file in "${added[@]}"; do
    [ -e "$file" ] || continue
    case "$file" in
        python/python3/*|node/node_modules/*|libIME2/*|json/*|*/vendor/*)
            continue
            ;;
    esac
    checked=$((checked + 1))
    if ! head -n 40 "$file" | grep -Eq "$declaration"; then
        printf 'missing AI declaration: %s\n' "$file"
        missing=1
    fi
done

printf 'checked %d added file(s)\n' "$checked"
[ "$missing" -eq 0 ]
